import React from "react";
import { Link } from "react-router-dom";
import "../css/Dashboard.css";

const ManagerDashboard = ({ user }) => {
  return (
    <div className="dashboard-container">
      <h1>Hoş geldin, {user?.name}!</h1>
      <p>Buradan çalışanları ve izin taleplerini yönetebilirsiniz.</p>

      <div className="dashboard-sections">
        {/* Çalışan Listesi */}
        <div className="dashboard-section">
          <h2>Çalışan Yönetimi</h2>
          <Link to="/employees">
            <button>Çalışan Listesi</button>
          </Link>
          <Link to="/add-employee">
            <button>Çalışan Ekle</button>
          </Link>
        </div>

        {/* Genel İzin Geçmişi */}
        <div className="dashboard-section">
          <h2>İzin Yönetimi</h2>
          <Link to="/leave-request">
            <button>Genel İzin Geçmişi</button>
          </Link>
        </div>
      </div>
    </div>
  );
};

export default ManagerDashboard;
